  double totalSignedArea = 0;
  double totalLength = 0;
  double numXPnt = 0;
  double numYPnt = 0;
  double numXLin = 0;
  double numYLin = 0;
  double numXPly = 0;
  double numYPly = 0;
  TYPE highestType = TYPE.POINT;

