      root.midX /= totalLength;
      root.midY /= totalLength;
    }
  } else {
    // numerator is sum of triangle centroids times triangle signed area
    // divide by total signed area per http://www.faqs.org/faqs/graphics/algorithms-faq/
    root.midX = numXPly;
    root.midY = numYPly;
